using System;

class NullReferenceDemo
{
    static void Main()
    {
        // CAUSE: Accessing a property on a null string
        string? name = null;
        // Console.WriteLine(name.Length); // Throws NullReferenceException

        // FIX: Use null-conditional operator
        int? length = name?.Length;
        Console.WriteLine(length ?? 0); // Prints 0 safely

        // FIX: Use string.IsNullOrEmpty (older approach)
        if (!string.IsNullOrEmpty(name))
        {
            Console.WriteLine(name.Length);
        }
        else
        {
            Console.WriteLine("Name is null or empty");
        }

        // CAUSE: Method returning null
        Person? person = GetPerson();
        // Console.WriteLine(person.Age); // Throws NullReferenceException

        // FIX: Null-forgiving operator (only if you KNOW it's not null)
        Console.WriteLine(person!.Age); // Use carefully!
    }

    static Person? GetPerson()
    {
        return null; // Simulating a failed lookup
    }
}

