using System;

class FormatDemo
{
    static void Main()
    {
        string userInput = "abc";

        // RISKY: int.Parse throws FormatException on bad input
        try
        {
            int result = int.Parse(userInput);
            Console.WriteLine(result);
        }
        catch (FormatException)
        {
            Console.WriteLine("Please enter a valid number");
        }

        // SAFER: TryParse returns false instead of throwing
        if (int.TryParse(userInput, out int result2))
        {
            Console.WriteLine($"Parsed: {result2}");
        }
        else
        {
            Console.WriteLine("Please enter a valid number");
        }
    }
}

using System;

class BankAccount
{
    public decimal Balance { get; private set; }

    public void Deposit(decimal amount)
    {
        // Guard clause: validate argument immediately
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(amount),
                amount,
                "Deposit amount must be greater than zero");

        Balance += amount;
        Console.WriteLine($"Deposited: {amount:C}. New balance: {Balance:C}");
    }

    public void Withdraw(decimal amount)
    {
        if (amount <= 0)
            throw new ArgumentOutOfRangeException(
                nameof(amount),
                "Withdrawal amount must be greater than zero");

        if (amount > Balance)
            throw new InvalidOperationException(
                "Insufficient funds for this withdrawal");

        Balance -= amount;
        Console.WriteLine($"Withdrew: {amount:C}. New balance: {Balance:C}");
    }
}

class GuardClauseDemo
{
    static void Main()
    {
        var account = new BankAccount { Balance = 1000m };

        try { account.Deposit(-50m); }
        catch (ArgumentOutOfRangeException ex)
        {
            Console.WriteLine($"Validation error: {ex.Message}");
        }

        try { account.Withdraw(2000m); }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine($"Business rule error: {ex.Message}");
        }
    }
}

using System;
using System.IO;

class FileIODemo
{
    static void ReadConfig(string filePath)
    {
        try
        {
            string content = File.ReadAllText(filePath);
            Console.WriteLine(content);
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine($"Config file not found: {ex.FileName}");
        }
        catch (DirectoryNotFoundException ex)
        {
            Console.WriteLine($"Directory not found: {ex.Message}");
        }
        catch (UnauthorizedAccessException ex)
        {
            Console.WriteLine($"Permission denied: {ex.Message}");
        }
        catch (IOException ex)
        {
            Console.WriteLine($"I/O error: {ex.Message}");
        }
    }
}

using System;

// Step 1: Define the custom exception
[Serializable]
public class InvalidScoreException : Exception
{
    public int Score { get; }

    public InvalidScoreException(int score)
        : base($"Score {score} is outside the valid range of 0-100")
    {
        Score = score;
    }

    public InvalidScoreException(int score, string message)
        : base(message)
    {
        Score = score;
    }

    public InvalidScoreException(int score, string message, Exception inner)
        : base(message, inner)
    {
        Score = score;
    }
}

// Step 2: Use the custom exception in business logic
public class GameScoreManager
{
    public void RecordScore(int score)
    {
        if (score < 0 || score > 100)
        {
            throw new InvalidScoreException(score);
        }
        Console.WriteLine($"Score recorded: {score}");
    }
}

class CustomExceptionDemo
{
    static void Main()
    {
        var manager = new GameScoreManager();

        try
        {
            manager.RecordScore(150); // Invalid!
        }
        catch (InvalidScoreException ex)
        {
            Console.WriteLine($"Custom error: {ex.Message}");
            Console.WriteLine($"Offending score: {ex.Score}");
        }
    }
}

using System;

class ExceptionInspector
{
    static void LogException(Exception ex)
    {
        Console.WriteLine("=== Exception Details ===");
        Console.WriteLine($"Message:     {ex.Message}");
        Console.WriteLine($"Source:      {ex.Source}");
        Console.WriteLine($"Type:        {ex.GetType().FullName}");
        Console.WriteLine($"Target:      {ex.TargetSite?.Name}");
        Console.WriteLine($"Stack Trace: {ex.StackTrace}");

        if (ex.InnerException != null)
        {
            Console.WriteLine("\n--- Inner Exception ---");
            Console.WriteLine($"Message: {ex.InnerException.Message}");
            Console.WriteLine($"Type:    {ex.InnerException.GetType().FullName}");
        }
    }

    static void Main()
    {
        try
        {
            try
            {
                int.Parse("not-a-number");
            }
            catch (FormatException fe)
            {
                throw new InvalidOperationException("Failed to process user input", fe);
            }
        }
        catch (Exception ex)
        {
            LogException(ex);
        }
    }
}
